// Preventive maintenance and calibration (docs/spec/mantenimiento.md, section 5). A plan belongs to a
// piece of equipment and is due by time (every N days, weeks or months) or by use (every N units of one
// of its meters). When it's due (leadDays before, for time) its work order is generated by itself, one at
// a time: while one is open, no other. Done → the next one counts from that day (or from that reading);
// cancelled → that one is skipped. Calibration plans are what Quality sees in its calibration
// prerequisite, without copying them. Plans and meters are archived, never deleted.
import type { TenantDb } from "../../db/tenant.ts";
import type { MaintPlanKind, MaintPlanUnit, Prisma } from "../../generated/prisma/client.ts";
import { maintenanceTexts } from "../../i18n/index.ts";
import { AppError, forbidden, notFound } from "../../lib/errors.ts";
import { auditAdmin, type AdminContext } from "../admin/admin-context.ts";
import { dayOf } from "../expiries/expiries.service.ts";
import { companyToday } from "../quality/prps.service.ts";
import { canViewQuality } from "../quality/quality-access.ts";
import {
  canViewMaintenance,
  canWorkMaintenance,
  dateOf,
  requireAny,
  requireMaintenance,
  requireManage,
  requireWork,
} from "./maintenance-access.ts";
import { maintenanceEnabled } from "./quality-link.ts";
import { assertTechnician, insertWorkOrder, namesOf } from "./work-orders.service.ts";

const OPEN = ["REPORTED", "PLANNED", "IN_PROGRESS", "ON_HOLD"] as const;
const DUE_SOON_DAYS = 7;

// ─── Days ───────────────────────────────────────────────────────────────────

export function addDays(day: string, days: number): string {
  const date = new Date(`${day}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

/** The day `every` units after `day`; a month later from the 31st is the last day of the month. */
export function addInterval(day: string, every: number, unit: MaintPlanUnit): string {
  if (unit === "DAYS") return addDays(day, every);
  if (unit === "WEEKS") return addDays(day, every * 7);
  const [year = 0, month = 1, date = 1] = day.split("-").map(Number);
  const target = new Date(Date.UTC(year, month - 1 + every, 1));
  const last = new Date(
    Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0),
  ).getUTCDate();
  target.setUTCDate(Math.min(date, last));
  return target.toISOString().slice(0, 10);
}

// ─── Views ──────────────────────────────────────────────────────────────────

export type PlanState = "ok" | "due_soon" | "overdue";

export interface PlanView {
  id: string;
  asset: { id: string; code: string; name: string } | null;
  kind: MaintPlanKind;
  name: string;
  instructions: string;
  checklist: string[];
  every: number | null;
  everyUnit: MaintPlanUnit | null;
  meter: { id: string; name: string; unit: string; lastValue: number | null } | null;
  meterEvery: number | null;
  nextMeterAt: number | null;
  assignedTo: { id: string; name: string } | null;
  estimatedMinutes: number | null;
  leadDays: number;
  lockout: boolean;
  nextDueOn: string | null;
  lastDoneOn: string | null;
  state: PlanState;
  openWorkOrder: { id: string; code: string } | null;
  archived: boolean;
}

const planSelect = {
  id: true,
  assetId: true,
  kind: true,
  name: true,
  instructions: true,
  checklist: true,
  every: true,
  everyUnit: true,
  meterId: true,
  meterEvery: true,
  assignedToId: true,
  estimatedMinutes: true,
  leadDays: true,
  lockout: true,
  nextDueOn: true,
  nextMeterAt: true,
  lastDoneOn: true,
  archivedAt: true,
  createdById: true,
} as const;

type PlanRow = Prisma.MaintPlanGetPayload<{ select: typeof planSelect }>;

function stateOf(
  plan: Pick<PlanRow, "nextDueOn" | "nextMeterAt" | "meterEvery">,
  meterValue: number | null,
  today: string,
): PlanState {
  if (plan.nextDueOn !== null) {
    const due = dayOf(plan.nextDueOn);
    if (due < today) return "overdue";
    return due <= addDays(today, DUE_SOON_DAYS) ? "due_soon" : "ok";
  }
  if (plan.nextMeterAt !== null && meterValue !== null) {
    if (meterValue >= plan.nextMeterAt) return "overdue";
    const margin = Math.ceil((plan.meterEvery ?? 0) / 10);
    return meterValue >= plan.nextMeterAt - margin ? "due_soon" : "ok";
  }
  return "ok";
}

async function views(db: TenantDb, rows: PlanRow[]): Promise<PlanView[]> {
  if (rows.length === 0) return [];
  const today = await companyToday(db);
  const [assets, meters, open, names] = await Promise.all([
    db.maintAsset.findMany({
      where: { id: { in: [...new Set(rows.map((row) => row.assetId))] } },
      select: { id: true, code: true, name: true },
    }),
    db.maintMeter.findMany({
      where: {
        id: { in: rows.flatMap((row) => (row.meterId === null ? [] : [row.meterId])) },
      },
      select: { id: true, name: true, unit: true, lastValue: true },
    }),
    db.maintWorkOrder.findMany({
      where: { planId: { in: rows.map((row) => row.id) }, status: { in: [...OPEN] } },
      select: { id: true, planId: true, year: true, number: true },
    }),
    namesOf(
      db,
      rows.map((row) => row.assignedToId),
    ),
  ]);
  const assetOf = new Map(assets.map((asset) => [asset.id, asset]));
  const meterOf = new Map(meters.map((meter) => [meter.id, meter]));
  const openOf = new Map(open.map((order) => [order.planId, order]));
  return rows.map((row) => {
    const meter = row.meterId === null ? undefined : meterOf.get(row.meterId);
    const order = openOf.get(row.id);
    return {
      id: row.id,
      asset: assetOf.get(row.assetId) ?? null,
      kind: row.kind,
      name: row.name,
      instructions: row.instructions,
      checklist: row.checklist,
      every: row.every,
      everyUnit: row.everyUnit,
      meter: meter ?? null,
      meterEvery: row.meterEvery,
      nextMeterAt: row.nextMeterAt,
      assignedTo:
        row.assignedToId === null
          ? null
          : { id: row.assignedToId, name: names.get(row.assignedToId) ?? "" },
      estimatedMinutes: row.estimatedMinutes,
      leadDays: row.leadDays,
      lockout: row.lockout,
      nextDueOn: row.nextDueOn === null ? null : dayOf(row.nextDueOn),
      lastDoneOn: row.lastDoneOn === null ? null : dayOf(row.lastDoneOn),
      state: stateOf(row, meter?.lastValue ?? null, today),
      openWorkOrder:
        order === undefined
          ? null
          : { id: order.id, code: maintenanceTexts.code(order.year, order.number) },
      archived: row.archivedAt !== null,
    };
  });
}

const ORDER: Record<PlanState, number> = { overdue: 0, due_soon: 1, ok: 2 };

export async function listPlans(
  ctx: AdminContext,
  query: { archived: boolean },
): Promise<PlanView[]> {
  await requireMaintenance(ctx);
  if (!canViewMaintenance(ctx)) throw forbidden();
  const rows = await ctx.db.maintPlan.findMany({
    where: { archivedAt: query.archived ? { not: null } : null },
    orderBy: [{ nextDueOn: "asc" }, { name: "asc" }],
    take: 2000,
    select: planSelect,
  });
  const list = await views(ctx.db, rows);
  return list.sort((a, b) => ORDER[a.state] - ORDER[b.state]);
}

/** The calibration plans, for Quality's calibration prerequisite (docs/spec/mantenimiento.md, decision 5). */
export async function calibrationPlans(ctx: AdminContext): Promise<PlanView[]> {
  await requireMaintenance(ctx);
  if (!canViewMaintenance(ctx) && !canViewQuality(ctx)) throw forbidden();
  const rows = await ctx.db.maintPlan.findMany({
    where: { archivedAt: null, kind: "CALIBRATION" },
    orderBy: [{ nextDueOn: "asc" }, { name: "asc" }],
    take: 500,
    select: planSelect,
  });
  const list = await views(ctx.db, rows);
  return list.sort((a, b) => ORDER[a.state] - ORDER[b.state]);
}

// ─── Changing ───────────────────────────────────────────────────────────────

export interface PlanInput {
  assetId: string;
  kind: MaintPlanKind;
  name: string;
  instructions: string;
  checklist: string[];
  /** By time: every N units, the first one on `firstDueOn`. */
  every: number | null;
  everyUnit: MaintPlanUnit | null;
  firstDueOn: string | null;
  /** By use: every N units of the meter, the first one at `firstMeterAt`. */
  meterId: string | null;
  meterEvery: number | null;
  firstMeterAt: number | null;
  assignedToId: string | null;
  estimatedMinutes: number | null;
  leadDays: number;
  lockout: boolean;
}

const bad = (message: string) => new AppError("BAD_REQUEST", { message });

async function checked(ctx: AdminContext, input: PlanInput) {
  const asset = await ctx.db.maintAsset.findFirst({
    where: { id: input.assetId },
    select: { id: true, archivedAt: true },
  });
  if (asset === null) throw notFound();
  if (asset.archivedAt !== null) throw bad(maintenanceTexts.errors.archived);
  await assertTechnician(ctx.db, input.assignedToId);
  const byTime = input.every !== null && input.everyUnit !== null;
  const byUse = input.meterId !== null && input.meterEvery !== null;
  if (byTime === byUse) throw bad(maintenanceTexts.errors.planFrequency);
  if (byUse) {
    const meter = await ctx.db.maintMeter.findFirst({
      where: { id: input.meterId ?? "", assetId: input.assetId, archivedAt: null },
      select: { id: true, lastValue: true },
    });
    if (meter === null) throw notFound();
    return {
      every: null,
      everyUnit: null,
      meterId: meter.id,
      meterEvery: input.meterEvery,
      nextMeterAt: input.firstMeterAt ?? (meter.lastValue ?? 0) + (input.meterEvery ?? 0),
      nextDueOn: null,
    };
  }
  const today = await companyToday(ctx.db);
  const first = input.firstDueOn ?? addInterval(today, input.every ?? 1, input.everyUnit ?? "DAYS");
  return {
    every: input.every,
    everyUnit: input.everyUnit,
    meterId: null,
    meterEvery: null,
    nextMeterAt: null,
    nextDueOn: dateOf(first),
  };
}

const fields = (input: PlanInput) => ({
  assetId: input.assetId,
  kind: input.kind,
  name: input.name,
  instructions: input.instructions,
  checklist: input.checklist.map((step) => step.trim()).filter((step) => step !== ""),
  assignedToId: input.assignedToId,
  estimatedMinutes: input.estimatedMinutes,
  leadDays: input.leadDays,
  lockout: input.lockout,
});

export async function createPlan(ctx: AdminContext, input: PlanInput): Promise<PlanView> {
  await requireManage(ctx);
  const schedule = await checked(ctx, input);
  const row = await ctx.db.maintPlan.create({
    data: { ...fields(input), ...schedule, createdById: ctx.tenant.membershipId },
    select: planSelect,
  });
  await auditAdmin(ctx, {
    action: "maintenance.plan.create",
    entityType: "MaintPlan",
    entityId: row.id,
    metadata: { name: row.name, kind: row.kind },
  });
  // Already due (or within its notice): its work order right away, not on the next round.
  await generateDue(ctx, await companyToday(ctx.db), [row.id]);
  return await planView(ctx, row.id);
}

export async function updatePlan(
  ctx: AdminContext,
  id: string,
  input: PlanInput & { archived?: boolean | undefined },
): Promise<PlanView> {
  await requireManage(ctx);
  const current = await ctx.db.maintPlan.findFirst({ where: { id }, select: planSelect });
  if (current === null) throw notFound();
  const schedule = await checked(ctx, input);
  const row = await ctx.db.maintPlan.update({
    where: { id },
    data: {
      ...fields(input),
      ...schedule,
      ...(input.archived === undefined
        ? {}
        : { archivedAt: input.archived ? (current.archivedAt ?? new Date()) : null }),
    },
    select: planSelect,
  });
  await auditAdmin(ctx, {
    action: "maintenance.plan.update",
    entityType: "MaintPlan",
    entityId: id,
    metadata: { name: row.name, archived: row.archivedAt !== null },
  });
  if (row.archivedAt === null) await generateDue(ctx, await companyToday(ctx.db), [id]);
  return await planView(ctx, id);
}

async function planView(ctx: AdminContext, id: string): Promise<PlanView> {
  const row = await ctx.db.maintPlan.findFirst({ where: { id }, select: planSelect });
  if (row === null) throw notFound();
  const [view] = await views(ctx.db, [row]);
  if (view === undefined) throw notFound();
  return view;
}

// ─── Generating the work orders ─────────────────────────────────────────────

/**
 * Generates the work orders of the plans that are due (all, or `only`), one per plan while none is
 * open. `ctx.info` is whoever acts (the worker: nobody). Returns how many were created.
 */
export async function generateDue(
  ctx: Pick<AdminContext, "db" | "info">,
  today: string,
  only?: readonly string[],
): Promise<number> {
  if (!(await maintenanceEnabled(ctx.db))) return 0;
  const plans = await ctx.db.maintPlan.findMany({
    where: { archivedAt: null, ...(only === undefined ? {} : { id: { in: [...only] } }) },
    select: planSelect,
    take: 5000,
  });
  if (plans.length === 0) return 0;
  const [open, meters, assets] = await Promise.all([
    ctx.db.maintWorkOrder.findMany({
      where: { planId: { in: plans.map((plan) => plan.id) }, status: { in: [...OPEN] } },
      select: { planId: true },
    }),
    ctx.db.maintMeter.findMany({
      where: {
        id: { in: plans.flatMap((plan) => (plan.meterId === null ? [] : [plan.meterId])) },
      },
      select: { id: true, lastValue: true },
    }),
    ctx.db.maintAsset.findMany({
      where: { id: { in: plans.map((plan) => plan.assetId) }, archivedAt: null },
      select: { id: true },
    }),
  ]);
  const busy = new Set(open.map((order) => order.planId));
  const reading = new Map(meters.map((meter) => [meter.id, meter.lastValue]));
  const live = new Set(assets.map((asset) => asset.id));
  let created = 0;
  for (const plan of plans) {
    if (busy.has(plan.id) || !live.has(plan.assetId)) continue;
    let dueOn: string | null = null;
    if (plan.nextDueOn !== null) {
      const due = dayOf(plan.nextDueOn);
      if (due <= addDays(today, plan.leadDays)) dueOn = due;
    } else if (plan.meterId !== null && plan.nextMeterAt !== null) {
      const value = reading.get(plan.meterId) ?? null;
      if (value !== null && value >= plan.nextMeterAt) dueOn = today;
    }
    if (dueOn === null) continue;
    await insertWorkOrder(ctx, plan.createdById, {
      title: plan.name,
      description: plan.instructions,
      assetId: plan.assetId,
      priority: "NORMAL",
      source: "PREVENTIVE",
      kind: plan.kind === "CALIBRATION" ? "CALIBRATION" : "PREVENTIVE",
      assignedToId: plan.assignedToId,
      dueOn,
      lockout: plan.lockout,
      planId: plan.id,
      checklist: plan.checklist,
    });
    created += 1;
  }
  return created;
}

/**
 * Its work order was done or cancelled: the plan moves on. Done counts the next one from today (or
 * from the meter's reading); cancelled skips that one. Then, if the next is already due, it's generated.
 */
export async function planWorkFinished(
  ctx: AdminContext,
  planId: string,
  action: "done" | "cancel",
): Promise<void> {
  const plan = await ctx.db.maintPlan.findFirst({ where: { id: planId }, select: planSelect });
  if (plan === null || plan.archivedAt !== null) return;
  const today = await companyToday(ctx.db);
  if (plan.every !== null && plan.everyUnit !== null) {
    const from = action === "done" || plan.nextDueOn === null ? today : dayOf(plan.nextDueOn);
    await ctx.db.maintPlan.update({
      where: { id: planId },
      data: {
        nextDueOn: dateOf(addInterval(from, plan.every, plan.everyUnit)),
        ...(action === "done" ? { lastDoneOn: dateOf(today) } : {}),
      },
      select: { id: true },
    });
  } else if (plan.meterId !== null && plan.meterEvery !== null) {
    const meter = await ctx.db.maintMeter.findFirst({
      where: { id: plan.meterId },
      select: { lastValue: true },
    });
    const from =
      action === "done" ? (meter?.lastValue ?? plan.nextMeterAt ?? 0) : (plan.nextMeterAt ?? 0);
    await ctx.db.maintPlan.update({
      where: { id: planId },
      data: {
        nextMeterAt: from + plan.meterEvery,
        ...(action === "done" ? { lastDoneOn: dateOf(today) } : {}),
      },
      select: { id: true },
    });
  }
  await generateDue(ctx, today, [planId]);
}

// ─── Meters ─────────────────────────────────────────────────────────────────

export interface MeterView {
  id: string;
  asset: { id: string; code: string; name: string } | null;
  name: string;
  unit: string;
  lastValue: number | null;
  lastReadAt: Date | null;
}

export async function listMeters(ctx: AdminContext): Promise<MeterView[]> {
  await requireAny(ctx);
  if (!canWorkMaintenance(ctx) && !canViewMaintenance(ctx)) throw forbidden();
  const rows = await ctx.db.maintMeter.findMany({
    where: { archivedAt: null },
    orderBy: [{ assetId: "asc" }, { name: "asc" }],
    take: 2000,
    select: { id: true, assetId: true, name: true, unit: true, lastValue: true, lastReadAt: true },
  });
  const assets = await ctx.db.maintAsset.findMany({
    where: { id: { in: [...new Set(rows.map((row) => row.assetId))] } },
    select: { id: true, code: true, name: true },
  });
  const assetOf = new Map(assets.map((asset) => [asset.id, asset]));
  return rows.map((row) => ({
    id: row.id,
    asset: assetOf.get(row.assetId) ?? null,
    name: row.name,
    unit: row.unit,
    lastValue: row.lastValue,
    lastReadAt: row.lastReadAt,
  }));
}

export async function createMeter(
  ctx: AdminContext,
  input: { assetId: string; name: string; unit: string },
): Promise<MeterView> {
  await requireManage(ctx);
  const asset = await ctx.db.maintAsset.findFirst({
    where: { id: input.assetId, archivedAt: null },
    select: { id: true, code: true, name: true },
  });
  if (asset === null) throw notFound();
  const row = await ctx.db.maintMeter.create({
    data: { assetId: asset.id, name: input.name, unit: input.unit },
    select: { id: true, name: true, unit: true, lastValue: true, lastReadAt: true },
  });
  await auditAdmin(ctx, {
    action: "maintenance.meter.create",
    entityType: "MaintMeter",
    entityId: row.id,
    metadata: { asset: asset.code, name: row.name },
  });
  return { ...row, asset };
}

/** A reading (whoever works in maintenance): never lower than the last one; it may make a plan due. */
export async function addReading(
  ctx: AdminContext,
  meterId: string,
  value: number,
): Promise<MeterView> {
  await requireWork(ctx);
  const meter = await ctx.db.maintMeter.findFirst({
    where: { id: meterId, archivedAt: null },
    select: { id: true, lastValue: true },
  });
  if (meter === null) throw notFound();
  if (meter.lastValue !== null && value < meter.lastValue) {
    throw bad(maintenanceTexts.errors.readingLower(meter.lastValue));
  }
  const now = new Date();
  await ctx.db.maintMeterReading.create({
    data: { meterId, value, membershipId: ctx.tenant.membershipId, readAt: now },
    select: { id: true },
  });
  await ctx.db.maintMeter.update({
    where: { id: meterId },
    data: { lastValue: value, lastReadAt: now },
    select: { id: true },
  });
  const plans = await ctx.db.maintPlan.findMany({
    where: { meterId, archivedAt: null },
    select: { id: true },
  });
  if (plans.length > 0) {
    await generateDue(
      ctx,
      await companyToday(ctx.db),
      plans.map((plan) => plan.id),
    );
  }
  const [view] = (await listMeters(ctx)).filter((candidate) => candidate.id === meterId);
  if (view === undefined) throw notFound();
  return view;
}
